var DEMO_FLAG_LINE = /^hans_kanban_demo: true$/m;
async function removeDemoBoard(app, demoFolder = DEFAULT_DEMO_FOLDER) {
  const folder = app.vault.getFolderByPath((0, import_obsidian2.normalizePath)(demoFolder));
  if (!(folder instanceof import_obsidian2.TFolder)) {
    new import_obsidian2.Notice(t("demo.removeMissing"));
    return;
  }
  try {
    let kept = 0;
    for (const child of [...folder.children]) {
      if (!(child instanceof import_obsidian2.TFile)) {
        kept++;
        continue;
      }
      const isDemo = child.extension === "base" || child.extension === "md" && DEMO_FLAG_LINE.test(await app.vault.read(child));
      if (isDemo) {
        await app.fileManager.trashFile(child);
      } else {
        kept++;
      }
    }
    if (kept === 0) {
      await app.fileManager.trashFile(folder);
      new import_obsidian2.Notice(t("demo.removed"));
    } else {
      new import_obsidian2.Notice(t("demo.removedPartial"));
    }
  } catch (error) {
    console.error("[hans-kanban] demo board removal failed", error);
    new import_obsidian2.Notice(t("demo.removeFailed"));
  }
}
